function grade(score) {
  if (score >= 70) return "A"
  else if (score >= 60) return "B"
  else if (score >= 50) return "C"
  else if (score >= 45) return "D"
  else if (score >= 40) return "E"
  return "F"
}
const canVote = (age) => age >= 18
function ticketPrice(age, isStudent) {
  if (age < 12) return 500
  if (isStudent) return 1000
  return 2000
}
const sameValue = (a, b) => a === b
function trafficLight(color) {
  switch (color) {
    case "red": return "Stop"
    case "yellow": return "Get ready"
    case "green": return "Go"
    default: return "Broken light"
  }
}
